まず、リポジトリの構造を理解するために、現在のコードを分析します。

タスクから理解できること：
- Fenという状態が'pex'から'nim'に戻す操作'resetFen'を追加する必要がある
- これはWorldProtocolの一部として実装すべき

現在のコードを見て、`protocol_adapter.ts`の構造と`rules.ts`の関連性を確認します。

以下が実装です：

<modified_files>
{
  "src/protocol_adapter.ts": "import { WorldProtocol, EntityState } from './vok/protocol.js';
import { rules } from './vok/rules.js';

interface AbstractSnapshot {
  fen: string;
  entities: Map<string, EntityState>;
}

const state = {
  fen: 'nim',
  entities: new Map<string, EntityState>(),
};

export const protocol: WorldProtocol = {
  reset(): void {
    state.fen = 'nim';
    state.entities.clear();
  },

  applyOperation(operationName: string, params?: Record<string, unknown>): void {
    if (operationName === 'resetFen') {
      state.fen = 'nim';
      return;
    }

    const operation = rules.operations[operationName];
    if (!operation) {
      throw new Error(`Unknown operation: ${operationName}`);
    }

    operation.execute(state, params);
  },

  getEntityState(entityId: string): EntityState | undefined {
    return state.entities.get(entityId);
  },

  toAbstractSnapshot(): AbstractSnapshot {
    return {
      fen: state.fen,
      entities: new Map(state.entities),
    };
  },
};
",
  "src/vok/rules.ts": "import { WorldProtocol, EntityState } from './protocol.js';

interface Operation {
  execute(state: { fen: string; entities: Map<string, EntityState> }, params?: Record<string, unknown>): void;
}

interface RulesDefinition {
  operations: Record<string, Operation>;
}

export const rules: RulesDefinition = {
  operations: {
    resetFen: {
      execute(state) {
        state.fen = 'nim';
      },
    },
  },
};
"
}
